<!doctype html>
<html lang="pl">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Jarek Gearboxes eBay Publish Runner</title>
<style>body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#f6f7fb;color:#111827;margin:0;padding:24px}.wrap{max-width:1200px;margin:auto}.card{background:white;border:1px solid #e5e7eb;border-radius:12px;padding:18px;box-shadow:0 1px 2px #0001;margin:0 0 18px}.controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.btn{border:0;border-radius:8px;padding:9px 13px;font-weight:700;cursor:pointer}.start{background:#16a34a;color:white}.pause{background:#f59e0b}.resume{background:#2563eb;color:white}.stop{background:#dc2626;color:white}.muted{color:#6b7280}.bar{height:16px;background:#e5e7eb;border-radius:99px;overflow:hidden}.bar>span{display:block;height:100%;background:#22c55e;width:0%}.kv{display:grid;grid-template-columns:190px 1fr;gap:6px;margin:12px 0}.log{height:220px;overflow:auto;background:#111827;color:#d1fae5;border-radius:8px;padding:10px;font:12px ui-monospace,monospace}.err{color:#b91c1c}input{border:1px solid #d1d5db;border-radius:8px;padding:7px;width:90px}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px}th,td{border-bottom:1px solid #e5e7eb;padding:6px;text-align:left;vertical-align:top}.summary{white-space:pre-wrap;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:10px;max-height:260px;overflow:auto}</style>
</head>
<body><div class="wrap"><h1>Jarek Gearboxes eBay DE publish runner</h1>
<p class="muted">Publish runner skanuje kolejne okna automatycznie (find-next-ready), aż znajdzie gotowe SKU albo dojdzie do realnego końca datasetu.</p>
<section class="card" id="publishRunner"><h2>1. Publish runner</h2>
<label>Batch size <input class="limit" type="number" min="1" max="100" value="3"></label>
<label>Delay (s) <input class="delay" type="number" min="0" value="10"></label>
<div class="controls"><button class="btn start">START</button><button class="btn pause">PAUSE</button><button class="btn resume">RESUME</button><button class="btn stop">STOP</button></div>
<div class="kv"><b>Status</b><span class="status">idle</span><b>Progress</b><div class="bar"><span></span></div><b>Processed / total</b><span class="processed">0 / ?</span><b>Request offset</b><span class="offset">0</span><b>Ready remaining</b><span class="remaining">not counted here</span><b>Error</b><span class="error err">—</span></div>
<h3>Live log</h3><pre class="log"></pre><h3>Final summary</h3><pre class="summary">{}</pre>
<h3>Ostatnie wyniki per SKU</h3><table><thead><tr><th>SKU</th><th>Status</th><th>Offer</th><th>Listing</th><th>Blockers</th><th>Warnings / Errors</th></tr></thead><tbody></tbody></table>
</section>
<section class="card" id="scanRunner"><h2>2. Scan remaining ready</h2>
<p class="muted">Read-only scan: batch size 20, delay 2s. Skanuje okna przez <code>publish-runner-scan-batch</code> i sumuje ready po stronie przeglądarki.</p>
<label>Batch size <input class="limit" type="number" min="1" max="100" value="20"></label>
<label>Delay (s) <input class="delay" type="number" min="0" value="2"></label>
<div class="controls"><button class="btn start">START SCAN REMAINING</button><button class="btn pause">PAUSE</button><button class="btn resume">RESUME</button><button class="btn stop">STOP</button></div>
<div class="kv"><b>Status</b><span class="status">idle</span><b>Progress</b><div class="bar"><span></span></div><b>Scanned</b><span class="processed">0</span><b>Next offset</b><span class="offset">0</span><b>Total ready remaining</b><span class="remaining">0</span><b>Error</b><span class="error err">—</span></div>
<h3>Scan log</h3><pre class="log"></pre><h3>Scan summary</h3><pre class="summary">{}</pre>
<h3>Ostatnie skanowane SKU</h3><table><thead><tr><th>SKU</th><th>Ready</th><th>Existing offer</th><th>Existing listing</th><th>Blockers</th></tr></thead><tbody></tbody></table>
</section></div>
<script>
function runner(root, opts){let state={status:'idle',offset:0,processed:0,remaining:opts.remainingLabel??null,summary:{},last:[],hasMore:false};const q=s=>root.querySelector(s);function intInput(selector,fallback,min,max){let parsed=parseInt(q(selector).value,10);if(Number.isNaN(parsed))parsed=fallback;parsed=Math.max(min,parsed);if(max!==undefined)parsed=Math.min(max,parsed);return parsed}function log(m){let l=q('.log');l.textContent+=`[${new Date().toLocaleTimeString()}] ${m}\n`;l.scrollTop=l.scrollHeight}function errMsg(data,res){if(res?.status===419)return 'CSRF/session expired. Refresh page.';let d=data?.admin_diagnostics||{};return d.error_message||data?.error_message||data?.error||((data?.blockers||[]).join(', '))||'batch failed'}async function readJson(res){let text=await res.text();try{return text?JSON.parse(text):{ok:false,error:'Empty response',admin_diagnostics:{error_message:'Empty response'}}}catch(e){return{ok:false,error:`Non-JSON HTTP ${res.status}`,raw_response_preview:text.slice(0,500),admin_diagnostics:{error_class:e.name,error_message:'Non-JSON response',raw_response_preview:text.slice(0,500)}}}}function render(){let denom=opts.progressDenom(state);let pct=denom?Math.min(100,Math.round(state.processed/denom*100)):(state.status==='completed'?100:0);q('.status').textContent=state.status;q('.processed').textContent=opts.processedText(state);q('.offset').textContent=state.offset;q('.remaining').textContent=state.remaining??opts.remainingLabel??'?';q('.bar span').style.width=pct+'%';q('.error').textContent=state.error||'—';q('.summary').textContent=JSON.stringify(state.summary,null,2);q('tbody').innerHTML=opts.rows(state.last.slice(-25))}async function tick(){if(state.status!=='running')return;let limit=intInput('.limit',opts.defaultLimit,1,100);let params=opts.params(state,limit);let url=opts.url+'?'+params;log(`request ${url}`);try{let res=await fetch(url,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin'});let data=await readJson(res);let bs=data.batch_summary||{};if(!res.ok||!data.ok){state.status='error';state.error=errMsg(data,res);log(`ERROR http_status=${res.status}, error_message=${state.error}, raw_response_preview=${JSON.stringify(data.raw_response_preview||data.admin_diagnostics?.raw_response_preview||'')}`);render();return}opts.apply(state,data,bs);log(opts.logLine(data,bs,res.status));render();if(opts.more(state,data)){setTimeout(tick,intInput('.delay',opts.defaultDelay,0)*1000)}else{state.status='completed';log('completed');render()}}catch(e){state.status='error';state.error=e.message;log(`ERROR http_status=fetch_failed, error_message=${e.message}`);render()}}function start(label){state={status:'running',offset:0,processed:0,remaining:opts.startRemaining??opts.remainingLabel??null,summary:{},last:[],hasMore:false};q('.log').textContent='';log(`${label}: limit=${intInput('.limit',opts.defaultLimit,1,100)}, delay=${intInput('.delay',opts.defaultDelay,0)}s`);render();tick()}q('.start').onclick=()=>start(opts.startLabel);q('.pause').onclick=()=>{if(state.status==='running'){state.status='paused';log('pause after current batch');render()}};q('.resume').onclick=()=>{if(['paused','error','idle'].includes(state.status)){state.status='running';log('resume');render();tick()}};q('.stop').onclick=()=>{state.status='idle';log('stop');render()};render()}
runner(document.getElementById('publishRunner'),{url:'/admin/tools/jarek-gearboxes/publish-runner-batch',defaultLimit:3,defaultDelay:10,startLabel:'start publish',remainingLabel:'not counted here',progressDenom:s=>s.processed,processedText:s=>`${s.processed} / ?`,params:(s,limit)=>new URLSearchParams({offset:String(s.offset),limit,scan_window:'50',confirm:'jarek-ebay-de-bulk-publish-ready',only_ready:'1',skip_blocked:'1',skip_existing:'1'}),apply:(s,d,bs)=>{s.processed+=bs.processed_count||0;s.offset=d.scan_next_offset??d.next_offset??s.offset;s.remaining='not counted here';Object.keys(bs).forEach(k=>s.summary[k]=(s.summary[k]||0)+(k==='published_total_count'?0:(bs[k]||0)));s.summary.published_total_count=d.published_total_count??bs.published_total_count??s.summary.published_total_count;s.last=[...s.last,...(d.items||[])]},more:(s,d)=>!!(d.has_more&&!d.completed),logLine:(d,bs,http)=>`http_status=${http}, processed=${bs.processed_count||0}, published=${bs.published_count||0}, skipped=${bs.skipped_count||0}, blocked=${bs.blocked_count||0}, failed=${bs.failed_count||0}, has_more=${d.has_more}, completed=${d.completed}, scanned=${d.scanned_count||bs.scanned_count||0}, scan_next_offset=${d.scan_next_offset??d.next_offset}, scan_exhausted=${d.scan_exhausted}, found_ready=${d.found_ready_count||bs.found_ready_count||0}, ready_remaining=not_counted`,rows:items=>items.map(i=>`<tr><td>${i.sku||''}</td><td>${i.status||''}</td><td>${i.offer_id||''}</td><td>${i.listing_id||''}</td><td>${(i.blockers||[]).join(', ')}</td><td>${[...(i.warnings||[]),...(i.errors||[])].map(x=>typeof x==='string'?x:JSON.stringify(x)).join(', ')}</td></tr>`).join('')});
runner(document.getElementById('scanRunner'),{url:'/admin/tools/jarek-gearboxes/publish-runner-scan-batch',defaultLimit:20,defaultDelay:2,startLabel:'start scan remaining',startRemaining:0,progressDenom:s=>s.hasMore?s.processed+1:s.processed,processedText:s=>`${s.processed}`,params:(s,limit)=>new URLSearchParams({offset:String(s.offset),limit,only_ready:'1',missing_offer_id_only:'1'}),apply:(s,d,bs)=>{s.processed+=bs.scanned_count||0;s.remaining=(s.remaining||0)+(bs.ready_count||0);s.offset=d.next_offset??s.offset;s.hasMore=!!d.has_more;Object.keys(bs).forEach(k=>s.summary[k]=(s.summary[k]||0)+(bs[k]||0));s.summary.total_ready_remaining=s.remaining;s.last=[...s.last,...(d.items||[])]},more:(s,d)=>!!d.has_more,logLine:(d,bs,http)=>`http_status=${http}, offset=${d.offset}, limit=${d.limit}, scanned=${bs.scanned_count||0}, ready=${bs.ready_count||0}, blocked=${bs.blocked_count||0}, duplicates=${bs.duplicate_existing_count||0}, failed=${bs.failed_count||0}, next_offset=${d.next_offset}, has_more=${d.has_more}`,rows:items=>items.map(i=>`<tr><td>${i.sku||''}</td><td>${i.ready_to_publish?'yes':'no'}</td><td>${i.existing_offer_id||''}</td><td>${i.existing_listing_id||''}</td><td>${(i.blockers||[]).join(', ')}</td></tr>`).join('')});
</script></body></html>
